    input  [3:0] in,
    output       out_and,
    output       out_or,
    output       out_xor
);
    wire [3:0] and_chain;
    wire [3:0] or_chain;
    wire [3:0] xor_chain;
    assign and_chain[0] = in[0];
    assign and_chain[1] = and_chain[0] & in[1];
    assign and_chain[2] = and_chain[1] & in[2];
    assign and_chain[3] = and_chain[2] & in[3];
    assign or_chain[0] = in[0];
    assign or_chain[1] = or_chain[0] | in[1];
    assign or_chain[2] = or_chain[1] | in[2];
    assign or_chain[3] = or_chain[2] | in[3];
    assign xor_chain[0] = in[0];
    assign xor_chain[1] = xor_chain[0] ^ in[1];
    assign xor_chain[2] = xor_chain[1] ^ in[2];
    assign xor_chain[3] = xor_chain[2] ^ in[3];
    assign out_and = and_chain[3];
    assign out_or = or_chain[3];
    assign out_xor = xor_chain[3];
endmodule

